(async () => {
/**
 * 拼多多发品 · 「指定类目 → 强制假一赔十品牌」扫描器
 * ------------------------------------------------------------------
 * 用法：在已登录的商家后台页面（如发布页）打开控制台，粘贴本文件，然后：
 *
 *     await scanForcedBrands(5908)                  // 扫一个类目
 *     await scanForcedBrands(5908, { download: true })   // 扫完自动下载 CSV
 *     await scanForcedBrands([5908, 5918, 22224])   // 批量扫多个类目
 *
 * 判定口径：
 *   must === true  →  该「类目 × 品牌」组合下，假一赔十被强制勾选且勾选框禁用（点不掉）
 *   notShow === true → 该组合下假一赔十整项隐藏
 *
 * 数据来源（两个平台接口，均需商家登录态）：
 *   1) 类目品牌表： GET  /draco-ms/mms/template/mall/brand?catId=<cat_id>
 *      → result.modules[*].propertys[] 里 pid===5 的那个属性即「品牌」，其 values 为本类目的候选品牌
 *   2) 规则判定：   POST /glide/v2/mms/query/rules/limit/new
 *      → body { cat_id, goods_type, goods_properties:[{ ref_pid:310, vid }] }
 *      → result.is_must_fake_one_lose_ten / is_not_show_fake_one_lose_ten
 *
 * 注意：
 *   - cat_id 必须是三级或四级（末级）类目，否则规则接口报 100002
 *   - ref_pid 310 是品牌属性位，实测跨类目稳定
 *   - 平台限流报错为 error_code 55555，本脚本内置指数退避重试
 */

const ARK_BRAND_PID = 5;          // 品牌属性 pid
const ARK_BRAND_REF_PID = 310;    // 品牌属性位 ref_pid
const ARK_CONCURRENCY = 5;

/** 通用 POST（带限流退避） */
async function arkPost(url, body, tries = 5) {
  for (let a = 0; a < tries; a++) {
    try {
      const r = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(body)
      });
      const j = await r.json();
      if (j && j.success) return { ok: true, result: j.result };
      if (j && j.error_code === 55555) { await new Promise(s => setTimeout(s, 2000 * (a + 1))); continue; }
      return { ok: false, error: (j && (j.error_msg || j.errorMsg)) || 'unknown' };
    } catch (e) {
      await new Promise(s => setTimeout(s, 1200 * (a + 1)));
    }
  }
  return { ok: false, error: 'retry-exhausted' };
}

/** 通用 GET */
async function arkGet(url) {
  const r = await fetch(url, { credentials: 'include' });
  return await r.json();
}

/** 取某类目的候选品牌表（vid + 名称） */
async function fetchCategoryBrands(catId) {
  const j = await arkGet('/draco-ms/mms/template/mall/brand?catId=' + catId);
  if (!j || j.success === false || !j.result) return null;
  let prop = null;
  const walk = o => {
    if (!o || typeof o !== 'object' || prop) return;
    if (Array.isArray(o)) { o.forEach(walk); return; }
    if (o.pid === ARK_BRAND_PID && o.values) { prop = o; return; }
    Object.keys(o).forEach(k => { if (k !== 'values') walk(o[k]); });
  };
  walk(j.result);
  if (!prop) return null;
  const v = prop.values;
  let arr = [];
  if (Array.isArray(v)) arr = v;
  else if (Array.isArray(v.content)) arr = v.content;
  else Object.keys(v).forEach(k => { if (Array.isArray(v[k])) arr = arr.concat(v[k]); });
  return arr.map(x => ({ vid: x.vid, name: x.value })).filter(x => x.vid !== undefined);
}

/** 判定单个「类目 × 品牌」组合 */
async function mustFolt(catId, brandVid) {
  const r = await arkPost('/glide/v2/mms/query/rules/limit/new', {
    cat_id: catId,
    goods_type: 1,
    goods_properties: brandVid ? [{ ref_pid: ARK_BRAND_REF_PID, vid: brandVid }] : []
  });
  if (!r.ok) return { error: r.error };
  return {
    must: r.result.is_must_fake_one_lose_ten,
    notShow: r.result.is_not_show_fake_one_lose_ten,
    goodsPatternList: r.result.goods_pattern_list
  };
}

/** 扫描：返回该类目下所有品牌 + 各自是否强制 */
async function scanForcedBrands(catId, opts) {
  opts = opts || {};
  const brands = await fetchCategoryBrands(catId);
  if (!brands) return { catId: catId, error: '拿不到该类目的品牌表（类目不存在 / 非末级 / 登录态失效）' };

  const rows = new Array(brands.length);
  let idx = 0;
  const worker = async () => {
    while (idx < brands.length) {
      const i = idx++;
      const b = brands[i];
      const r = await mustFolt(catId, b.vid);
      rows[i] = { catId: catId, vid: b.vid, name: b.name, must: r.must === true, notShow: r.notShow === true, error: r.error || '' };
    }
  };
  await Promise.all(Array.from({ length: opts.concurrency || ARK_CONCURRENCY }, worker));

  const base = await mustFolt(catId, 0);
  const res = {
    catId: catId,
    brandCount: brands.length,
    baselineMust: base.must === true,
    forcedCount: rows.filter(r => r.must).length,
    notShowCount: rows.filter(r => r.notShow).length,
    forced: rows.filter(r => r.must),
    notForced: rows.filter(r => !r.must && !r.notShow),
    hidden: rows.filter(r => r.notShow),
    all: rows
  };
  if (opts.download) arkDownloadCsv('强制假一赔十_' + catId + '.csv', rows.filter(r => r.must).map(r => [r.catId, r.vid, r.name]));
  return res;
}

/** 批量扫描多个类目 */
async function scanForcedBrandsBatch(catIds, opts) {
  const out = [];
  for (const c of catIds) out.push(await scanForcedBrands(c, opts));
  const allForced = out.reduce((a, x) => a.concat(x.forced || []), []);
  if (opts && opts.download) {
    arkDownloadCsv('强制假一赔十_批量_' + catIds.length + '类目.csv', allForced.map(r => [r.catId, r.vid, r.name]));
  }
  return { cats: catIds.length, totalForcedPairs: allForced.length, perCategory: out.map(x => ({ catId: x.catId, brands: x.brandCount, forced: x.forcedCount, error: x.error || '' })), allForced: allForced };
}

/** 下载 CSV（UTF-8 BOM，Excel 直接打开不乱码） */
function arkDownloadCsv(filename, rows, header) {
  header = header || ['cat_id', 'brand_vid', 'brand_name'];
  const q = s => '"' + String(s === undefined || s === null ? '' : s).replace(/"/g, '""') + '"';
  const csv = '\uFEFF' + [header.map(q).join(',')].concat(rows.map(r => r.map(q).join(','))).join('\r\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 3000);
}

// 便捷：把结果打印成表格
function arkPrint(result) {
  if (result.error) { console.error(result); return; }
  console.log('类目 ' + result.catId + '：候选品牌 ' + result.brandCount + ' 个，其中强制假一赔十 ' + result.forcedCount + ' 个');
  console.table(result.forced.map(r => ({ VID: r.vid, 品牌: r.name })));
}

